import random
random.seed(7)
secret_number = random.randint(1, 10)
guesses = [2, 9, secret_number]
for user_guess in guesses:
    if user_guess == secret_number:
        print('Congratulations!', user_guess, 'is right!')
    else:
        print(user_guess, 'is too far off — try again!')
